// Helper to build custom 10-key number pad
function addNumberPad(frame, yPos) {
  const numPad = figma.createFrame();
  numPad.name = "Number Pad";
  numPad.resize(327, 224);
  numPad.x = 24; numPad.y = yPos;
  numPad.fills = [];

  const keys = [
    ["1", "2", "3"],
    ["4", "5", "6"],
    ["7", "8", "9"],
    ["*", "0", "⌫"]
  ];

  const kw = 327 / 3;
  const kh = 224 / 4;

  for (let r = 0; r < 4; r++) {
    for (let c = 0; r === 3 && c === 2 ? c < 3 : c < 3; c++) {
      const keyVal = keys[r][c];
      const keyFrame = figma.createFrame();
      keyFrame.name = `Key_${keyVal}`;
      keyFrame.resize(kw - 8, kh - 8);
      keyFrame.x = c * kw + 4; keyFrame.y = r * kh + 4;
      keyFrame.fills = []; // borderless clear look
      keyFrame.cornerRadius = 8;

      const keyText = figma.createText();
      keyText.fontName = { family: "Inter", style: "Semi Bold" };
      keyText.fontSize = 22;
      keyText.characters = keyVal;
      keyText.fills = [{ type: 'SOLID', color: { r: 0.1, g: 0.12, b: 0.18 } }];
      keyText.x = (kw - 8 - keyText.width) / 2; keyText.y = (kh - 8 - keyText.height) / 2;

      keyFrame.appendChild(keyText);
      numPad.appendChild(keyFrame);
    }
  }
  frame.appendChild(numPad);
}

