// Helper function to build beautiful Tab bar component
function addTabBar(parentFrame, currentTab) {
  const tabBar = figma.createFrame();
  tabBar.name = "Navigation Tab Bar";
  tabBar.resize(375, 64);
  tabBar.x = 0; tabBar.y = 812 - 34 - 64;
  tabBar.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
  tabBar.strokes = [{ type: 'SOLID', color: { r: 0.94, g: 0.95, b: 0.96 } }];

  const tabs = [
    { name: "Home", icon: homeIconOrig, active: currentTab === "Home" },
    { name: "Portfolio", icon: portfolioIconOrig, active: currentTab === "Portfolio" },
    { name: "Trade", icon: tradeIconOrig, active: currentTab === "Trade" },
    { name: "Market", icon: marketIconOrig, active: currentTab === "Market" },
    { name: "Profile", icon: profileIconOrig, active: currentTab === "Profile" }
  ];

  const tw = 375 / 5;
  tabs.forEach((tab, index) => {
    const tabFrame = figma.createFrame();
    tabFrame.name = tab.name;
    tabFrame.resize(tw, 64);
    tabFrame.x = index * tw; tabFrame.y = 0;
    tabFrame.fills = [];

    const icon = tab.icon.createInstance();
    icon.resize(24, 24);
    icon.x = (tw - 24) / 2; icon.y = 12;

    const activeColor = { r: 0.243, g: 0.322, b: 0.757 };
    const inactiveColor = { r: 0.506, g: 0.533, b: 0.596 };

    function recolor(node) {
      if (node.fills && node.fills.length > 0) {
        node.fills = [{ type: 'SOLID', color: tab.active ? activeColor : inactiveColor }];
      }
      if (node.strokes && node.strokes.length > 0) {
        node.strokes = [{ type: 'SOLID', color: tab.active ? activeColor : inactiveColor }];
      }
      if ('children' in node) node.children.forEach(recolor);
    }
    recolor(icon);
    tabFrame.appendChild(icon);

    const label = figma.createText();
    label.fontName = { family: "Inter", style: "Medium" };
    label.fontSize = 10;
    label.characters = tab.name;
    label.fills = [{ type: 'SOLID', color: tab.active ? activeColor : inactiveColor }];
    label.x = (tw - label.width) / 2; label.y = 40;
    tabFrame.appendChild(label);

    tabBar.appendChild(tabFrame);
  });

  parentFrame.appendChild(tabBar);
}

