    logo.x = 0; logo.y = 6;
    row.appendChild(logo);
  }

  const tickTxt = figma.createText();
  tickTxt.fontName = { family: "Inter", style: "Bold" };
  tickTxt.fontSize = 14;
  tickTxt.characters = ticker;
  tickTxt.fills = [{ type: 'SOLID', color: { r: 0.051, g: 0.051, b: 0.071 } }];
  tickTxt.x = 44; tickTxt.y = 4;
  row.appendChild(tickTxt);

  const nameTxt = figma.createText();
  nameTxt.fontName = { family: "Inter", style: "Regular" };
  nameTxt.fontSize = 12;
  nameTxt.characters = name;
  nameTxt.fills = [{ type: 'SOLID', color: { r: 0.506, g: 0.533, b: 0.596 } }];
  nameTxt.x = 44; nameTxt.y = 22;
  row.appendChild(nameTxt);

  // Trend mini sparkline
  const spark = figma.createVector();
  spark.vectorPaths = [{
    windingRule: "EVENODD",
    data: isGain ? "M 0 10 L 10 2 L 20 8 L 30 0" : "M 0 2 L 10 10 L 20 4 L 30 10"
  }];
  spark.strokes = [{ type: 'SOLID', color: isGain ? { r: 0.18, g: 0.75, b: 0.52 } : { r: 0.996, g: 0.314, b: 0.314 } }];
  spark.strokeWeight = 1.5;
  spark.x = 180; spark.y = 16;
  row.appendChild(spark);

  // Price & Change on the far right
  const priceTxt = figma.createText();
  priceTxt.fontName = { family: "Inter", style: "Bold" };
  priceTxt.fontSize = 14;
  priceTxt.characters = price;
  priceTxt.fills = [{ type: 'SOLID', color: { r: 0.051, g: 0.051, b: 0.071 } }];
  priceTxt.x = 327 - priceTxt.width; priceTxt.y = 4;
  row.appendChild(priceTxt);

  const changeTxt = figma.createText();
  changeTxt.fontName = { family: "Inter", style: "Medium" };
  changeTxt.fontSize = 12;
  changeTxt.characters = change;
  changeTxt.fills = [{ type: 'SOLID', color: isGain ? { r: 0.18, g: 0.75, b: 0.52 } : { r: 0.996, g: 0.314, b: 0.314 } }];
  changeTxt.x = 327 - changeTxt.width; changeTxt.y = 22;
  row.appendChild(changeTxt);

  parentFrame.appendChild(row);
}

